// ─────────────────────────────────────────────────────────────────────────────
// Normalize Input with Category Fast Path Detection
// ─────────────────────────────────────────────────────────────────────────────
const body = $json.body || $json;
const query = $json.query || {};
const base64 = body.file || body.data || body.base64;
let mimeType = (body.mimeType || body.mimetype || '').toLowerCase();
const fileName = body.fileName || body.filename || '';

// 1. Check explicit category from payload body or URL query parameter
let explicitCategory = (body.category || body.doc_type || body.type || query.category || query.type || '').toLowerCase();

// 2. If category is not in body/query, check Webhook node name for fast path
if (!explicitCategory || explicitCategory === 'auto') {
  const nodeName = $node.name || '';
  if (nodeName.includes('Khmer ID')) explicitCategory = 'khmer_id';
  else if (nodeName.includes('Passport')) explicitCategory = 'passport';
  else if (nodeName.includes('CV')) explicitCategory = 'cv';
  else if (nodeName.includes('Certificate')) explicitCategory = 'certificate';
  else if (nodeName.includes('Invoice')) explicitCategory = 'invoice';
  else explicitCategory = null;
}

if (!base64) {
  throw new Error('Missing field: file. Send JSON with { file: <base64>, mimeType, fileName }');
}

// Auto-detect MIME from fileName if not provided
if (!mimeType && fileName) {
  const ext = fileName.split('.').pop().toLowerCase();
  const MIME_MAP = {
    jpg: 'image/jpeg', jpeg: 'image/jpeg',
    png: 'image/png', webp: 'image/webp',
    pdf: 'application/pdf',
    docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  };
  mimeType = MIME_MAP[ext] || 'application/octet-stream';
}

let routeFormat;
if (mimeType.startsWith('image/')) routeFormat = 'image';
else if (mimeType === 'application/pdf') routeFormat = 'pdf';
else if (mimeType.includes('wordprocessingml')) routeFormat = 'docx';
else throw new Error('Unsupported MIME type: ' + mimeType + '. Use image/*, application/pdf, or .docx');

return [{ json: { routeFormat, base64, mimeType, fileName, explicitCategory: explicitCategory || null } }];

// Check if category was provided explicitly in payload/webhook
const normalizeNode = $('Normalize Input').first();
const explicitCategory = normalizeNode ? normalizeNode.json.explicitCategory : null;
const validCategories = ['khmer_id', 'passport', 'cv', 'certificate', 'invoice'];

const item = $input.first();

if (explicitCategory && validCategories.includes(explicitCategory)) {
  return [{
    json: {
      format: item.json.format,
      extractedText: item.json.extractedText || null,
      category: explicitCategory,
      confidence: 100,
      bypassedClassifier: true
    },
    binary: item.binary
  }];
}

return [{
  json: {
    format: item.json.format,
    extractedText: item.json.extractedText || null,
    category: null,
    confidence: null,
    bypassedClassifier: false
  },
  binary: item.binary
}];

// ─────────────────────────────────────────────────────────────────────────────
// Parse Classifier Result
// ─────────────────────────────────────────────────────────────────────────────
function tryGet(nodeName) {
  try { return $(nodeName).first(); } catch (e) { return null; }
}

function extractJson(raw) {
  if (!raw) return null;
  let text = raw.trim().replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
  try { return JSON.parse(text); } catch (e) {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) { try { return JSON.parse(match[0]); } catch (e) {} }
  return null;
}

const raw = $json.output || $json.text || '';
const parsed = extractJson(raw);

const validCategories = ['khmer_id', 'passport', 'cv', 'certificate', 'invoice'];
const category = (parsed && validCategories.includes(parsed.category)) ? parsed.category : 'unknown';
const confidence = (parsed && typeof parsed.confidence === 'number') ? parsed.confidence : 0;

if (category === 'unknown') {
  throw new Error('Classifier returned unknown category. Raw: ' + raw);
}

const priorItem = tryGet('Prepare Image') || tryGet('Prepare PDF') || tryGet('Prepare DOCX');

return [{
  json: {
    format: priorItem ? priorItem.json.format : 'unknown',
    extractedText: priorItem ? (priorItem.json.extractedText || null) : null,
    category,
    confidence,
    bypassedClassifier: false
  },
  binary: priorItem ? priorItem.binary : undefined
}];

